window.guidedView=function(t,e,esc){
 const key=t.id+':'+e?.event_round,g=window.GUIDES[key],o=e?.original_event;
 if(!o)return '<article class="card"><h3>No change was selected in this round</h3><p>That does not mean nothing changed. Choose a named case on the left, or read this trajectory’s full text.</p><button data-inspect="trajectory">Read all ten stories</button></article>';
 const quote=(label,text,kind='')=>`<article class="evidence-quote ${kind}"><div class="eyebrow">${esc(label)}</div><blockquote>${esc(text||'No supporting passage was selected.')}</blockquote></article>`;
 const generic={title:'Inspect this selected textual change',short:o.action,change:'Selected textual change',source:'Source remains provisional',behavior:'Not established',takeaway:o.source_reason,before:'Compare the earlier own wording with the new clause. A selected change is not automatically a new strategy.',sourceWhy:o.source_reason,behaviorWhy:o.behavior_testability};
 const c=g||generic;
 let out=`<p class="case-rule">${esc(c.short)}</p><div class="answer-row"><div><span>1 · Does the story change?</span><strong>${esc(c.change)}</strong></div><div><span>2 · Did it come from the peer?</span><strong>${esc(c.source)}</strong></div><div><span>3 · Does it change play?</span><strong>${esc(c.behavior)}</strong></div></div><p class="case-takeaway">${esc(c.takeaway)}</p>`;
 out+=`<section class="case-section"><div class="section-number">1</div><div><h3>What changed?</h3><p>${esc(c.before)}</p><div class="quote-pair">${quote('Earlier own story · round '+o.before_round,o.before_quote)}${quote('New own story · round '+e.event_round,o.after_quote,'new-quote')}</div></div></section>`;
 if(c.timeline){out+=`<section class="case-section"><div class="section-number">↳</div><div><h3>${esc(c.timeline.title)}</h3><div class="clause-track">${c.timeline.steps.map(s=>`<button class="clause-step ${s.state}" data-evidence-round="${s.rounds[0]}" data-evidence-quote="${esc(s.quote||'')}" data-evidence-note="${esc(s.detail||s.quote)}"><span>Round${s.rounds.length>1?'s':''} ${s.rounds.join(', ')}</span><strong>${esc(s.label)}</strong><small>Read the story</small></button>`).join('')}</div><p class="hint">${esc(c.timeline.note)}</p></div></section>`;}
 if(c.schedule){out+=`<section class="case-section"><div class="section-number">↳</div><div><h3>The advice becomes a fuller schedule</h3><p>Each dot is a percentage named in the story—not an observed action. Empty positions mean no percentage was specified at that amount.</p><div class="schedule-wrap"><div class="schedule"><div></div>${['1','2','3','4','4.5','Near 5'].map(x=>`<div class="schedule-head">Sent: ${x}</div>`).join('')}<div class="schedule-row-label">Round 8</div>${[null,null,'≈50%',null,null,'≈60%+'].map(x=>`<div class="schedule-point">${x?`<span>${x}</span>`:'<span class="unspecified">—</span>'}</div>`).join('')}<div class="schedule-row-label">Round 10</div>${['≈30%','40%','50%','55%','57%','≥60%'].map(x=>`<div class="schedule-point new"><span>${x}</span></div>`).join('')}</div></div><p class="hint">Return shares are of the received amount. “Perhaps,” “about,” “closer to,” and “or more” are approximate advice, not exact thresholds.</p><button data-evidence-round="8">Read round 8</button> <button data-evidence-round="10">Read round 10</button></div></section>`;}
 out+=`<section class="case-section"><div class="section-number">2</div><div><h3>Where might it have come from?</h3><div class="quote-pair">${quote('Peer story actually shown · source round '+t.rounds[e.event_round-1].exposed?.round,o.exposed_quote,'peer-quote')}${quote('What this agent writes next · round '+e.event_round,o.after_quote,'new-quote')}</div><p>${esc(c.sourceWhy)}</p>${c.extraUnseen?quote('Not shown to this agent · comparison from another run',o.unseen_quote):`<details><summary>Check the unseen comparison</summary>${quote('Different run · not an exposure',o.unseen_quote)}</details>`}</div></section>`;
 out+=`<section class="case-section"><div class="section-number">3</div><div><h3>Did it then behave differently?</h3><p class="behavior-answer">${esc(c.behavior)}</p><p>${esc(c.behaviorWhy)}</p>`;
 if(c.amount)out+='<div class="causal-order"><div><span>Game · round 4</span><strong>Sends 3</strong><small>Before writing</small></div><div><span>Myth · round 4</span><strong>“three-fifths”</strong><small>Rule stated</small></div><div><span>Game · round 5</span><strong>Sends 3</strong><small>After writing</small></div></div>';
 out+=`<p class="hint">A change in text, a possible source, and a behavioral effect are three different findings.</p></div></section><div class="inspect-more"><strong>Want to check the underlying evidence?</strong><div><button data-inspect="sources">Full source passages</button><button data-inspect="trajectory">All ten stories</button><button data-inspect="behavior">Game values & timing</button><button data-inspect="plots">Raw plots & event map</button></div><p>48 trajectories / 45 runs. The 44 selected examples are not a census. Interpretations remain provisional.</p></div><dialog id="story-dialog"><button id="close-story">Close story</button><h3 id="story-heading"></h3><p id="story-note" class="hint"></p><div id="story-body" class="story-body"></div></dialog>`;
 return out;
};
